from lib import *
M=mcq;F=tf;S=short;N=num
chapter(4,'maths','equal-groups','Equal Groups',
 ('Animal jumps','A frog, a squirrel, a rabbit and a kangaroo jump along a number line to reach their food. The frog jumps 3 steps at a time, the squirrel 4, the rabbit 6 and the kangaroo 8. The numbers they land on are called multiples.'),
 [('Multiples',['The frog starting at 0 lands on 3, 6, 9, 12, 15, 18 and so on; these numbers are multiples of 3.','The squirrel jumps 4 steps and lands on 4, 8, 12, 16 and so on, which are multiples of 4. To reach 60 it needs 15 jumps because 4 x 15 = 60.','The rabbit jumps 6 steps, so it lands on 6, 12, 18 and so on. The smallest 3-digit number it lands on is 102, after 17 jumps, because 6 x 17 = 102.','The kangaroo jumps 8 steps and lands on 8, 16, 24 and so on. The frog does not touch 67 because 67 is not a multiple of 3.']),
  ('Common multiples',['Numbers that two animals both touch are common multiples.','The frog (3) and the squirrel (4) both touch 12, 24 and 36, which are common multiples of 3 and 4.','The rabbit (6) and the kangaroo (8) both touch 24 and 48, so these are common multiples of 6 and 8.','To reach 48 the rabbit jumps 8 times and the kangaroo 6 times, and to reach 60 the frog jumps 20 times and the rabbit 10 times. The bigger the step, the fewer the jumps.']),
  ('Chase puzzle',['A cat is on 6 and a rat is on 12. The cat jumps 3 steps and the rat jumps 2 steps each time.','After each jump the cat is on 9, 12, 15, 18, 21, 24 and the rat is on 14, 16, 18, 20, 22, 24.','They land together on 24, so the cat catches the rat at 24, after 6 jumps.','We also look for multiplication and division sentences hidden in a number grid, like 3 x 4 = 12 and 12 / 4 = 3.'])],
 [('The squirrel jumps 4 steps at a time. How many jumps to reach 60?',[('Each jump is 4 steps and it must cover 60.','Count equal jumps.'),('60 divided by 4 is 15, so 15 jumps.','Division finds the number of equal jumps.')]),
  ('Find a common multiple of 3 and 4 greater than 12.',[('Multiples of 3: 3, 6, 9, 12, 15, 18, 21, 24.','List multiples of 3.'),('Multiples of 4: 4, 8, 12, 16, 20, 24. Both lists contain 24, so 24 is a common multiple.','Find a number in both lists.')])],
 ('Explain what multiples and common multiples are using the animals.',['Multiples are made by jumping equal steps','Common multiples appear in both lists','More steps means fewer jumps'],['67 is a multiple of 3']),
 ['Multiples of a number come from equal jumps.','Common multiples are shared by two numbers.','Bigger steps need fewer jumps.'],
 [M('1',1,'Which is a multiple of 3?','12',[('13','13 is not in the 3 times table'),('14','14 is not in the 3 times table')],'3 x 4 = 12.'),
  N('2',1,'How many jumps of 4 steps to reach 60?',15,'4 x 15 = 60.',[(14,'4 x 14 is 56')]),
  F('3',1,'The frog touches 67 when jumping 3 steps at a time.',False,'67 is not a multiple of 3.'),
  M('4',2,'Which number do both the frog (3 steps) and the squirrel (4 steps) touch?','12',[('10','The frog does not land on 10'),('15','The squirrel does not land on 15')],'12 is a multiple of both 3 and 4.'),
  N('5',2,'How many jumps does the rabbit (6 steps) need to reach 48?',8,'6 x 8 = 48.',[(6,'That is the kangaroo\'s count')]),
  M('6',2,'The cat starts at 6 and jumps 3, the rat starts at 12 and jumps 2. Where does the cat catch the rat?','24',[('18','The cat is on 18 when the rat is on 20'),('30','They meet before 30')],'Both land on 24 after 6 jumps.'),
  S('7',3,'Name a common multiple of 6 and 8.',['24','48','72'],'24 and 48 are common multiples of 6 and 8.'),
  F('8',3,'The bigger the jump, the fewer jumps are needed to reach the same number.',True,'The kangaroo needs fewer jumps than the rabbit for 48.')])
chapter(4,'maths','elephants-tigers-and-leopards','Elephants, Tigers and Leopards',
 ('The NIM game','Two players add 1 or 2 each time to reach the target number 10. The player who reaches 10 first wins. There is a clever way to be sure of winning, and the addition chart is full of patterns too.'),
 [('Playing NIM',['Player 1 picks 1 or 2. Player 2 adds 1 or 2 to it, and the players keep adding to the total.','Whoever reaches 10 first wins. Play several rounds and keep notes.','Try other targets like 11 or 12 and see for which numbers you are sure to win.']),
  ('Winning idea',['If the other player has reached 6 and it is your turn, add 1 to reach 7. Then whatever the other adds, 8 or 9, you reach 10 and win.','If the other player has reached 7 and it is your turn, you will lose if they play well, because you can only reach 8 or 9 and they then reach 10.','If the other player has reached 8 and it is your turn, add 2 and you reach 10 and win.','So the numbers 7, 4 and 1 are good numbers to reach: from them you can always bring the total to 10.']),
  ('The addition chart',['The chart lists sums from 0 + 0 up to 12 + 12 in a table, and each cell is row plus column.','Each row goes up by 1 as we move right, and each column goes up by 1 as we move down.','The number 9 appears in many cells, but the number 24 appears only once.','The sum of two even numbers is even, and the sum of two odd numbers is also even.'])],
 [('Target 10, adding 1 or 2. The other player is at 8 and it is your turn. What do you do?',[('You need 2 to go from 8 to 10.','Check the gap to the target.'),('Add 2 and you reach 10 first, so you win.','Reaching 10 wins the game.')]),
  ('Why does reaching 7 make you win in the game of 10?',[('From 7 the opponent can only reach 8 or 9.','They add 1 or 2.'),('From 8 you add 2 and from 9 you add 1 to reach 10, so you win.','You always have the right move.')])],
 ('Explain how to win the target-10 NIM game.',['Reach 7, 4 or 1','Opponent adds 1 or 2','Then you add the number that makes 10'],['The first player always wins whatever they play']),
 ['In NIM you add 1 or 2 to reach the target first.','Reaching 7 (then 10) is a winning plan.','The addition chart shows patterns in sums.'],
 [M('1',1,'In the game with target 10, you are on 8. What should you add to win?','2',[('1','That makes 9 and the other wins'),('3','You can only add 1 or 2')],'8 + 2 = 10.'),
  F('2',1,'In NIM you may add any number you like.',False,'You can only add 1 or 2 each time.'),
  N('3',1,'What is 12 + 12 in the addition chart?',24,'The last cell of the table is 12 + 12 = 24.',[(12,'That is one addend')]),
  M('4',2,'The other player is on 6 and it is your turn. What should you add?','1, to reach 7',[('2, to reach 8','Then the other player adds 2 and wins'),('Nothing','You must add 1 or 2')],'From 7 you can always reach 10 next.'),
  M('5',2,'What does each row of the chart do as you move right?','Goes up by 1',[('Goes down by 1','It increases'),('Stays the same','It changes')],'Moving right adds 1 to the column number.'),
  S('6',2,'Which totals are winning numbers to reach in target 10? Give one.',['7','4','1'],'From 7, 4 or 1 you can always bring the total to 10.'),
  F('7',3,'The sum of two even numbers is always even.',True,'Even numbers are made of pairs, so two of them also make pairs.'),
  M('8',3,'The other player is on 7 and it is your turn. What will happen with best play?','You will lose',[('You will win','They reach 10 next'),('Draw','Someone reaches 10')],'You can only reach 8 or 9, and then they reach 10.')])
chapter(4,'maths','fun-with-symmetry','Fun with Symmetry',
 ('Ink butterflies','Fold a paper, put drops of colour on the fold and press. Open it, and you get a pattern that looks the same on both sides. We saw the same in rangolis and masks. Today we learn why.'),
 [('Line of symmetry',['A line that divides a design into two equal halves, so that one half is the mirror image of the other, is a line of symmetry.','The ink design opened from a folded paper has its line of symmetry along the fold.','Rangolis, masks, bead strings and buildings often have symmetry.']),
  ('Paper airplane',['A paper aeroplane is made by folding along the middle. The fold line is its line of symmetry.','Place a mirror along the line and the half you see matches the other half.','An aeroplane with no line of symmetry, called asymmetrical, may not fly straight, so try making both and see which flies longer.']),
  ('Folding and cutting',['If you fold a paper once and cut a shape along the fold, you get a symmetrical shape when you open it.','Fold the paper twice and cut at a corner, and the holes appear in four places.','Where you cut on a folded paper decides where the holes appear when you open it, so predict first and then check.']),
  ('Symmetry in shapes',['We draw shapes on a dot grid and find which are symmetrical and mark their lines of symmetry.','Some shapes have one line of symmetry and some have more.','A mirror placed along the line of symmetry shows the same shape again.'])],
 [('How do you find a line of symmetry of a butterfly picture?',[('Look for a line that splits the picture into two matching halves.','Both halves should look the same.'),('Fold along that line: if the halves fit exactly, it is a line of symmetry.','Folding is a check.')]),
  ('A paper is folded in half and a triangle is cut from the fold. What do you see on opening?',[('The triangle is cut on both halves at the same place.','The fold line is a line of symmetry.'),('You see a diamond hole, symmetrical about the fold.','Both sides match.')])],
 ('Explain what a line of symmetry is and how a mirror shows it.',['Two equal matching halves','Fold or mirror to check','Examples in rangoli and aeroplane'],['A symmetrical shape has no line']),
 ['A line of symmetry splits a shape into two matching halves.','A mirror along the line shows the same shape.','Cut-and-fold designs are symmetrical.'],
 [M('1',1,'What is a line of symmetry?','A line that divides a shape into two matching halves',[('Any line','It must make matching halves'),('A curved line only','It is usually straight')],'Both halves are mirror images of each other.'),
  F('2',1,'An ink blot on a folded and pressed paper makes a symmetrical pattern.',True,'The fold is the line of symmetry.'),
  M('3',1,'Where is the line of symmetry of a paper aeroplane?','Along its middle fold',[('At its tail','It is in the middle'),('It has none','It has one')],'The middle fold divides the aeroplane into two halves.'),
  S('4',2,'What do we call a shape that has no line of symmetry?',['asymmetrical','asymmetric'],'A shape without a line of symmetry is asymmetrical.'),
  M('5',2,'How can you check a line of symmetry?','Fold along it or place a mirror on it',[('Weigh it','Weight is not a test'),('Count the corners','Not enough')],'If the halves fit or the mirror shows the same shape, it is a line of symmetry.'),
  F('6',2,'A paper folded in half and cut along the fold gives a symmetrical shape.',True,'The two halves are cut at the same place.'),
  M('7',3,'Which of these is likely to have a line of symmetry?','A butterfly',[('A crumpled paper','It is irregular'),('A scribble','It has no pattern')],'A butterfly\'s two wings match.'),
  M('8',3,'A paper aeroplane with no line of symmetry will likely:','Not fly straight',[('Fly perfectly','Symmetry helps flying'),('Float on water','Not related')],'An asymmetrical plane may fly unevenly.')])
